// Prefer Task-returning methods so callers can await failures.
static async Task SaveAsync()
{
    await Task.Delay(10);
    throw new InvalidOperationException("save failed");
}

try
{
    await SaveAsync();
}
catch (InvalidOperationException ex)
{
    Console.WriteLine(ex.Message);
}

static async Task<int> ComputeAsync()
{
    await Task.Delay(10);
    return 42;
}

int value = await ComputeAsync(); // keep the call chain asynchronous
Console.WriteLine(value);

using var cts = new CancellationTokenSource();
Task worker = WorkerAsync(cts.Token);

cts.Cancel();
try
{
    await worker; // cancellation request is not shutdown completion
}
catch (OperationCanceledException) { }

static async Task WorkerAsync(CancellationToken token)
{
    await Task.Delay(100, token);
}

